def load():
    """Decode blobs into {font_key: (ascent, descent, glyphs)}.
    glyphs maps ord -> (w, h, dx, dy, adv, bytes).
    """
    out = {}
    for key, spec in FONTS.items():
        raw = zlib.decompress(base64.b64decode(spec['blob']))
        glyphs = {}
        for code, (w, h, dx, dy, adv, off, n) in \
                spec['glyphs'].items():
            glyphs[code] = (w, h, dx, dy, adv, raw[off:off + n])
        out[key] = (spec['ascent'], spec['descent'], glyphs)
    return out
